// Rust sm-protocol owns the schemas. --check compares generated bytes without writing them.
import { compile } from 'json-schema-to-typescript';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '../../..');
const names = ['application-v1', 'application-methods-v1', 'bridge-v1', 'foundation-errors'];
const check = process.argv[2] === '--check';
const output = process.argv[3] ? resolve(process.argv[3]) : resolve(root, 'packages/protocol/src/generated');
if ((!check && process.argv[2] !== '--output') || process.argv.length > 4 || (!check && process.argv.length !== 4)) {
  throw new Error('usage: generate.mjs --check [existing-directory] | --output <new-directory>');
}
if (!check) await mkdir(output); // never overwrite an existing generated source directory
let drift = false;
for (const name of names) {
  const schema = JSON.parse(await readFile(resolve(root, `schemas/${name}.schema.json`), 'utf8'));
  if (schema.$schema !== 'https://json-schema.org/draft/2020-12/schema') throw new Error('unexpected schema dialect');
  const text = await compile(schema, schema.title ?? 'FoundationErrorCode', {
    bannerComment: '/* Generated from sm-protocol JSON Schema; do not edit. Runtime validation uses Ajv. */',
    style: { singleQuote: true },
  });
  const dest = resolve(output, `${name}.ts`);
  if (check) {
    try {
      if (await readFile(dest, 'utf8') !== text) drift = true;
    } catch (error) {
      if (error.code === 'ENOENT') drift = true;
      else throw error;
    }
  } else {
    await writeFile(dest, text);
  }
}
if (drift) {
  console.error('Generated TypeScript differs from committed sources. Run reviewed generation explicitly.');
  process.exitCode = 1;
} else {
  console.log(check ? 'S01-TS-GEN-01 PASS: generated bytes match' : 'Generated TypeScript into explicit new directory');
}
